use std::collections::HashSet;

/// Removes duplicates from a vector of integers.
///
/// # Parameters
/// - `nums`: A vector of integers.
///
/// # Returns
/// A vector of integers containing only the unique elements from the input vector.
///
/// # Specification
/// ## Requires
/// - `nums` must be a vector of integers.
///
/// ## Ensures
/// - The returned vector contains only unique integers.
/// - The order of the first occurrence of each unique integer in `nums` is preserved in the result.
/// - The length of the returned vector is less than or equal to the length of `nums`.
///
/// ## Invariant
/// - At any point in the loop, `seen` contains all integers that have been added to `result`.
/// - The length of `result` is equal to the number of unique integers seen so far.
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();

    // Loop invariant: `seen` contains all integers added to `result`
    // and `result` contains unique integers in the order they were first seen.
    for &num in nums.iter() {
        // Precondition: `num` is an integer from `nums`
        // Postcondition: If `num` was not in `seen`, it will be added to `result`
        if seen.insert(num) {
            result.push(num);
        }
    }

    result
}

fn main() {
    let nums = vec![1, 2, 2, 3, 4, 4, 5];
    let unique_nums = remove_duplicates(nums);
    println!("{:?}", unique_nums); // Output: [1, 2, 3, 4, 5]
}